"""Append hand-written threat-intel examples to data/seed.jsonl to rebalance
the dataset toward the 25% threat-intel target. Facts verified by hand.
Run once: python scripts/add_threatintel.py
"""
import json

SYSTEM = ("You are a cybersecurity assistant for authorized security testing, "
          "CTFs, and education. Explain clearly and include detection and "
          "mitigation where relevant.")

# (user, assistant) pairs — all threat_intel domain
PAIRS = [
("Explain MITRE ATT&CK technique T1003 (OS Credential Dumping) and where credentials are typically harvested from.",
 "T1003 (OS Credential Dumping) covers adversaries stealing account credentials -- passwords, hashes, or Kerberos tickets -- from operating system stores so they can authenticate as legitimate users (feeding directly into T1078 Valid Accounts and lateral movement).\n\nCommon sources map to sub-techniques: T1003.001 LSASS memory (tools like Mimikatz read plaintext creds, NTLM hashes, and tickets from the lsass.exe process); T1003.002 the SAM registry hive (local account hashes); T1003.003 NTDS.dit (the Active Directory database on a domain controller, containing every domain account's hash -- the highest-value target); T1003.004 LSA secrets; and on Linux, /etc/shadow.\n\nDetection: monitor for suspicious process access to lsass.exe (Sysmon Event ID 10 with GrantedAccess masks like 0x1010/0x1410), use of known dumping tools or the comsvcs.dll MiniDump/procdump technique, volume shadow copy access to grab NTDS.dit or the SAM hive, and unexpected access to ntds.dit on domain controllers.\n\nMitigation: enable Credential Guard and LSA protection (RunAsPPL) to harden LSASS, restrict SeDebugPrivilege, keep privileged accounts off lower-trust hosts (tiered administration), and use EDR with behavioral credential-theft detection. Note: this is distinct from T1055 (Process Injection) -- credential dumping steals secrets, process injection hides code in another process."),

("Explain MITRE ATT&CK technique T1055 (Process Injection) and how defenders detect it.",
 "T1055 (Process Injection) covers adversaries running their code inside the address space of another, usually legitimate, process. The goal is defense evasion (malicious activity appears to come from a trusted process like explorer.exe) and often privilege escalation (inheriting the target process's context).\n\nCommon variants map to sub-techniques: T1055.001 DLL injection, T1055.002 PE injection, T1055.012 process hollowing (spawn a legitimate process suspended, unmap its image, and replace it with malicious code), and T1055.004 asynchronous procedure call (APC) injection.\n\nHow it typically works on Windows: allocate memory in the target (VirtualAllocEx), write the payload into it (WriteProcessMemory), and start execution (CreateRemoteThread, QueueUserAPC, or thread hijacking via SetThreadContext).\n\nDetection: behavioral EDR watching for that API call sequence across process boundaries, memory scanning for injected/unbacked executable regions (RWX private memory not backed by a file on disk), and anomalies like a normally-network-quiet process suddenly making outbound C2 connections. Sysmon Event ID 8 (CreateRemoteThread) and Event ID 10 (ProcessAccess) are useful telemetry.\n\nMitigation: EDR with anti-injection behavioral rules, Windows attack surface reduction (ASR) rules, and Protected Process Light for sensitive processes. Don't confuse this with T1003 (Credential Dumping) -- process injection is about executing code stealthily, not stealing credentials, though the two are frequently chained."),

("Explain MITRE ATT&CK technique T1053 (Scheduled Task/Job) and why it's used for both persistence and execution.",
 "T1053 (Scheduled Task/Job) covers adversaries abusing OS task-scheduling facilities to run malicious code -- Windows Task Scheduler (T1053.005), cron on Linux/macOS (T1053.003), systemd timers, and at.\n\nWhy it serves double duty: as execution, a task can immediately or repeatedly launch a payload; as persistence, a task configured to trigger at logon, at boot, or on a recurring schedule survives reboots and re-runs the payload without the attacker maintaining an active session. Scheduled tasks can also run as SYSTEM or another user, giving a privilege-context change as a bonus.\n\nDetection: on Windows, Security Event ID 4698 (scheduled task created), 4702 (task updated), and process-creation monitoring of schtasks.exe with /create; treat tasks whose action points at user-writable paths (AppData, Temp, Public) or references encoded/obfuscated commands as high-priority. On Linux, monitor changes to /etc/crontab, /etc/cron.*, and per-user crontabs, plus new systemd unit/timer files.\n\nMitigation: restrict who can create scheduled tasks (least privilege), baseline legitimate tasks and alert on deviations, forward task-creation events to a SIEM, and review the referenced payload (hash, signature, content) before clearing an alert -- some legitimate installers and updaters do stage tasks in temp locations."),

("Explain MITRE ATT&CK technique T1490 (Inhibit System Recovery) and its relationship to ransomware.",
 "T1490 (Inhibit System Recovery) covers adversaries deleting or disabling the built-in recovery features that would otherwise let a victim restore data or system state without paying -- it is a near-universal precursor step in modern ransomware attacks, executed just before or alongside the mass-encryption stage (T1486, Data Encrypted for Impact).\n\nTypical actions on Windows: deleting Volume Shadow Copies (vssadmin delete shadows /all /quiet, or wmic shadowcopy delete), resizing shadow storage to purge snapshots, disabling Windows recovery (bcdedit /set recoveryenabled no, bcdedit /set bootstatuspolicy ignoreallfailures), and clearing backup catalogs (wbadmin delete catalog).\n\nWhy attackers do it: shadow copies and system restore points would otherwise allow trivial recovery of encrypted files, undermining the extortion leverage -- so removing them maximizes pressure to pay.\n\nDetection: this is a high-value, high-confidence signal because legitimate use of these exact commands is rare -- alert on vssadmin/wmic shadowcopy deletion, bcdedit recovery-disabling flags, and wbadmin catalog deletion, ideally as an automated high-severity trigger since it often immediately precedes encryption.\n\nMitigation: maintain offline, immutable, or off-host backups (so shadow-copy deletion doesn't eliminate all recovery), restrict which accounts can run these administrative commands, and deploy EDR that can kill the process and isolate the host the moment recovery-inhibition commands are seen."),

("Summarize CVE-2019-0708 (BlueKeep) and why Microsoft treated it as unusually serious.",
 "CVE-2019-0708, known as BlueKeep, is a critical use-after-free vulnerability in Microsoft's Remote Desktop Services (RDP) that allows unauthenticated, pre-authentication remote code execution -- an attacker only needs network access to an exposed RDP service (TCP 3389), with no valid credentials and no user interaction. It carries a CVSS score of 9.8 and affects Windows 7, Windows Server 2008, Server 2008 R2, and older systems.\n\nWhy it was treated as unusually serious: the flaw is 'wormable,' meaning exploit code could self-propagate from machine to machine across networks without user action -- the same property that made WannaCry (via EternalBlue) so damaging in 2017. Microsoft took the rare step of releasing patches even for out-of-support operating systems like Windows XP and Server 2003, and both Microsoft and national agencies issued urgent advisories urging immediate patching before a reliable public worm emerged.\n\nMitigation: apply the patch; where patching is delayed, enable Network Level Authentication (NLA), which forces authentication before the vulnerable code path is reachable (partial mitigation, not a full fix); block or restrict RDP (TCP 3389) at the network perimeter and never expose it directly to the internet; and place RDP behind a VPN or gateway with MFA."),

("Summarize CVE-2020-1472 (Zerologon).",
 "CVE-2020-1472, dubbed Zerologon, is a critical privilege-escalation vulnerability (CVSS 10.0) in the Netlogon Remote Protocol (MS-NRPC) used by Windows domain controllers. It stems from a flawed use of AES in CFB8 mode with a fixed all-zero initialization vector during the Netlogon authentication handshake.\n\nHow it works: because of the IV flaw, roughly 1 in 256 attempts with an all-zero plaintext produces an all-zero ciphertext that the DC accepts as valid, letting an unauthenticated attacker with network access to a domain controller spoof the identity of any computer account -- including the domain controller's own machine account. By repeatedly trying, the attacker authenticates, then uses a follow-up Netlogon operation to set the DC machine account's password to empty, effectively granting domain-administrator-level control over Active Directory in seconds.\n\nImpact: complete domain compromise from an unauthenticated network position, requiring only connectivity to a DC.\n\nMitigation: apply Microsoft's phased patches (initial fix August 2020, enforcement mode February 2021), which enforce secure Netlogon channels and reject the vulnerable calls; monitor for anomalous Netlogon authentication and machine-account password changes (Event ID 4742 on the DC machine account is a red flag); and ensure domain controllers are not broadly reachable from untrusted network segments."),

("Summarize CVE-2017-5638 (the Apache Struts 2 RCE behind the Equifax breach).",
 "CVE-2017-5638 is a critical remote code execution vulnerability in the Apache Struts 2 web framework, specifically in the Jakarta Multipart parser. It allows an unauthenticated attacker to execute arbitrary commands by injecting a malicious Object-Graph Navigation Language (OGNL) expression into the Content-Type HTTP header of a crafted request; when the parser fails to handle the malformed header, it evaluates the attacker's OGNL expression server-side, leading to command execution in the context of the web application.\n\nSignificance: this is the vulnerability exploited in the 2017 Equifax breach, one of the largest and most consequential data breaches in history, exposing sensitive personal data of roughly 147 million people. Equifax had a vulnerable, unpatched Struts application exposed, and the flaw was exploited months after a patch was available, making it a canonical case study in the consequences of delayed patch management on internet-facing systems.\n\nMitigation: upgrade Struts to a patched version (the primary fix); as compensating controls, a WAF can block known OGNL-injection patterns in the Content-Type header, and internet-facing application inventory plus timely patching would have prevented the breach. The broader lesson is asset inventory and patch SLAs for public-facing software, since the window between disclosure and mass exploitation of such flaws is often very short."),

("Summarize CVE-2021-26855 (ProxyLogon) and how it was used in the wild.",
 "CVE-2021-26855 (ProxyLogon) is a server-side request forgery (SSRF) vulnerability in on-premises Microsoft Exchange Server that allows an unauthenticated attacker who can reach the Exchange server over HTTPS to send crafted requests and authenticate as the Exchange server itself, bypassing authentication.\n\nHow it was weaponized: ProxyLogon was chained with additional Exchange vulnerabilities disclosed at the same time (notably CVE-2021-27065, a post-authentication arbitrary file write) so that the SSRF-granted authentication led to writing a web shell to the server, achieving remote code execution. This chain gave attackers full control of the Exchange server, allowing mailbox access, credential theft, and a foothold for lateral movement.\n\nIn the wild: the chain was exploited at scale in early 2021, initially attributed to a state-sponsored group Microsoft tracks as HAFNIUM, and then rapidly by many other actors once details became public, leading to tens of thousands of compromised Exchange servers worldwide before organizations could patch.\n\nMitigation: apply Microsoft's out-of-band security updates (released March 2021); hunt for web shells written to Exchange virtual directories and anomalous Exchange process activity around the disclosure window; and reduce exposure by placing Exchange behind a VPN/reverse proxy with pre-authentication where feasible, or migrating off internet-facing on-prem Exchange."),

("Summarize CVE-2021-3156 (Sudo 'Baron Samedit').",
 "CVE-2021-3156, nicknamed Baron Samedit, is a heap-based buffer overflow in sudo -- the near-ubiquitous Unix/Linux utility for running commands with elevated privileges. It allows any local user to escalate to root, and critically requires no special sudo configuration and does not require the user to be listed in the sudoers file at all.\n\nRoot cause: when sudo runs in 'shell' mode (via sudoedit or the -s/-i flags), a flaw in how it unescapes backslashes in command-line arguments leads to a heap buffer overflow that an attacker can control to corrupt memory and gain root. The bug had been present in the codebase for roughly a decade before discovery (affecting sudo versions from 1.8.2 up to 1.9.5p1), making an enormous number of systems vulnerable.\n\nImpact: reliable local privilege escalation to root on a huge range of Linux and Unix systems, valuable to an attacker who already has any low-privilege foothold (e.g., via a compromised web app or SSH account) as a straightforward path to full system control.\n\nMitigation: update sudo to 1.9.5p2 or later (the patched version); since this is a local-escalation bug, defense in depth also means limiting how attackers gain that initial low-privilege foothold in the first place, and monitoring for unexpected sudo/sudoedit crashes or usage patterns."),

("Explain the Lockheed Martin Cyber Kill Chain and how defenders use it.",
 "The Cyber Kill Chain, developed by Lockheed Martin, is a model that breaks an intrusion into seven sequential stages, framing an attack as a chain an adversary must complete to succeed:\n\n1. Reconnaissance -- researching and selecting targets (OSINT, scanning).\n2. Weaponization -- pairing an exploit with a payload (e.g., a malicious document).\n3. Delivery -- transmitting the weapon to the target (phishing email, drive-by, USB).\n4. Exploitation -- triggering the vulnerability to execute code.\n5. Installation -- installing malware/backdoor to establish a foothold.\n6. Command and Control (C2) -- establishing a channel for the attacker to remotely operate.\n7. Actions on Objectives -- achieving the goal (data exfiltration, encryption, destruction).\n\nHow defenders use it: the core value is that disrupting any single stage breaks the chain and stops the attack, so defenders map their controls and detections to stages, identify gaps, and prioritize -- e.g., email filtering and user training target Delivery, EDR targets Exploitation/Installation, and egress filtering plus C2 detection target Command and Control. It also structures incident analysis by letting responders identify how far an intrusion progressed.\n\nLimitations: it's linear and somewhat malware/perimeter-centric, which is why it's often used alongside MITRE ATT&CK (more granular, non-linear technique catalog) and the Diamond Model (relationships between adversary, capability, infrastructure, and victim) for a fuller analytic picture."),

("Explain the 'Pyramid of Pain' concept in threat intelligence.",
 "The Pyramid of Pain, introduced by David Bianco, ranks types of indicators by how much 'pain' you cause an adversary when you detect and block that indicator -- specifically, how hard it is for the attacker to change it and keep operating. It guides where to invest detection effort for the most durable defensive value.\n\nFrom bottom (trivial for the attacker to change) to top (very hard):\n1. Hash values -- blocking a specific file hash is defeated by recompiling or changing a single byte; trivial pain.\n2. IP addresses -- attackers rotate IPs easily; low pain.\n3. Domain names -- slightly harder (registration, DNS), but still cheap to change; low-moderate pain.\n4. Network/host artifacts -- patterns like specific URI structures, User-Agent strings, or registry keys; moderate pain, since changing them means altering tooling.\n5. Tools -- detecting the actual malware or utility (e.g., a specific C2 framework's signatures) forces the attacker to find or build a new tool; high pain.\n6. TTPs (Tactics, Techniques, and Procedures) -- detecting behavior (how they move laterally, escalate, or exfiltrate) is the hardest for an adversary to change because it requires altering how they fundamentally operate; maximum pain.\n\nPractical takeaway: hash/IP/domain blocklists are useful but brittle and easily bypassed; the highest-leverage detection engineering targets tools and especially TTPs (which maps well onto MITRE ATT&CK), because behavior-based detection remains effective even as the attacker cycles through infrastructure and payloads."),

("What's the difference between an Indicator of Compromise (IOC) and an Indicator of Attack (IOA)?",
 "IOCs and IOAs are both signals defenders use, but they differ in what they describe and when they're useful.\n\nAn Indicator of Compromise (IOC) is a forensic artifact showing that a compromise has occurred or matching known-bad activity -- a malicious file hash, a C2 IP address or domain, a specific registry key or filename left by known malware, or a mutex used by a malware family. IOCs are inherently backward-looking and reactive: they're typically derived from a previous incident or threat report, so they tell you 'this specific known-bad thing is present,' which is valuable for detecting known threats but useless against a variant that changes those specific artifacts.\n\nAn Indicator of Attack (IOA) describes the behavior or intent of an attack in progress, independent of the specific tools or infrastructure used -- for example, a Word process spawning PowerShell that then makes an outbound connection, or a sequence of actions consistent with lateral movement and privilege escalation. IOAs are proactive and behavior-focused: they can catch novel or previously-unseen threats because they detect what the attacker is doing rather than matching a known artifact.\n\nHow they relate to the Pyramid of Pain: IOCs mostly live at the low, brittle end (hashes, IPs, domains that attackers change easily), while IOAs correspond to TTPs at the top (hard for attackers to change). Mature detection programs use both -- IOCs for fast, high-confidence matching of known threats, and IOA/behavioral detection for resilience against new and evolving ones."),

("Give a threat-intelligence overview of Cobalt Strike and why it matters to defenders.",
 "Cobalt Strike is a commercial adversary-simulation / red-team framework, legitimately sold for authorized penetration testing, but cracked and pirated versions are among the most commonly abused post-exploitation tools by real threat actors, including ransomware affiliates and state-sponsored groups. To defenders, 'Cobalt Strike Beacon activity' is frequently an indicator of a serious, hands-on-keyboard intrusion.\n\nKey components and behaviors: its primary payload is 'Beacon,' an implant that provides command execution, file transfer, keylogging, privilege escalation, and lateral movement. Beacon supports flexible C2, including HTTP/HTTPS and DNS, and can operate in an SMB 'peer-to-peer' mode over named pipes so that only one host talks to the internet while others beacon internally. Operators customize traffic using 'Malleable C2' profiles to make C2 blend in with legitimate-looking web traffic.\n\nDetection: JA3/JA3S TLS fingerprinting and known default Malleable C2 profile artifacts; default or predictable named-pipe names used by SMB Beacon; regular beaconing patterns (consistent interval plus jitter rather than human-like bursty traffic); memory scanning for Beacon's in-memory signatures; and default staging behaviors in unpatched or default-configured deployments. Threat-intel feeds also track known Cobalt Strike C2 server IPs/certificates.\n\nWhy it matters: because it's so widely abused, recognizing Beacon behavior early -- especially the beaconing pattern and lateral-movement tradecraft -- can catch an intrusion before it reaches the ransomware or data-exfiltration stage. Detection should emphasize behavior (TTPs) over specific IPs, since operators rotate infrastructure and tune profiles frequently."),

("Explain the Diamond Model of Intrusion Analysis.",
 "The Diamond Model of Intrusion Analysis is an analytic framework for describing and correlating intrusions around four core features, drawn as the vertices of a diamond:\n\n1. Adversary -- the actor or group conducting the intrusion (who).\n2. Capability -- the tools, malware, exploits, and techniques they use (how).\n3. Infrastructure -- the physical/logical resources used to deliver capabilities and maintain control (C2 servers, domains, email accounts) (what they use to operate).\n4. Victim -- the target organization, person, asset, or data (against whom).\n\nThe edges express relationships: an adversary uses a capability over some infrastructure against a victim. Analysts can pivot along these edges -- for example, starting from a piece of malware (capability), pivot to the C2 domains it contacts (infrastructure), then to other victims contacting the same infrastructure, then toward attribution of the adversary.\n\nWhy it's useful: it structures threat intelligence so that discovering one vertex helps discover others (pivoting), supports clustering related activity into campaigns, and captures relationships that a purely linear model like the Kill Chain doesn't. It complements rather than replaces the Kill Chain (which describes the stages of a single intrusion) and MITRE ATT&CK (which catalogs the specific techniques an adversary's 'capability' vertex might use). Together they give analysts stage, technique, and relationship views of the same activity."),
]

rows = []
with open("data/seed.jsonl") as f:
    rows = [json.loads(l) for l in f if l.strip()]

before = len(rows)
with open("data/seed.jsonl", "a") as f:
    for user, assistant in PAIRS:
        obj = {"domain": "threat_intel", "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": user},
            {"role": "assistant", "content": assistant},
        ]}
        f.write(json.dumps(obj, ensure_ascii=False) + "\n")

print(f"Added {len(PAIRS)} threat-intel rows: {before} -> {before+len(PAIRS)} total")
